sealed class PaymentMethod {
  data class Card(
    val isDefaultPaymentMethod: Boolean,
    val paymentToken: String,
    val cardScheme: String,
    val name: String,
    val expiryDate: String,
    val cardNumber: String,
    val nickName: String,
    val cardHolderName: String,
    val requiresCVV: Boolean,
    val created: String,
    val lastUsedAt: String,
  ) : PaymentMethod() {
    fun toHashMap(): HashMap<String, Any> {
      val hashMap = HashMap<String, Any>()
      hashMap["isDefaultPaymentMethod"] = isDefaultPaymentMethod
      hashMap["paymentToken"] = paymentToken
      hashMap["cardScheme"] = cardScheme
      hashMap["name"] = name
      hashMap["expiryDate"] = expiryDate
      hashMap["cardNumber"] = cardNumber
      hashMap["nickName"] = nickName
      hashMap["cardHolderName"] = cardHolderName
      hashMap["requiresCVV"] = requiresCVV
      hashMap["created"] = created
      hashMap["lastUsedAt"] = lastUsedAt
      return hashMap
    }
  }

  data class Wallet(
    val isDefaultPaymentMethod: Boolean,
    val paymentToken: String,
    val walletType: String,
    val created: String,
    val lastUsedAt: String,
  ) : PaymentMethod() {
    fun toHashMap(): HashMap<String, Any> {
      val hashMap = HashMap<String, Any>()
      hashMap["isDefaultPaymentMethod"] = isDefaultPaymentMethod
      hashMap["paymentToken"] = paymentToken
      hashMap["walletType"] = walletType
      hashMap["created"] = created
      hashMap["lastUsedAt"] = lastUsedAt
      return hashMap
    }
  }

  data class Error(
    val code: String,
    val message: String,
  ) : PaymentMethod() {
    fun toHashMap(): HashMap<String, Any> {
      val hashMap = HashMap<String, Any>()
      hashMap["code"] = code
      hashMap["message"] = message
      return hashMap
    }
  }
}

interface PaymentSessionHandler {
  fun getCustomerDefaultSavedPaymentMethodData(): PaymentMethod
  fun getCustomerLastUsedPaymentMethodData(): PaymentMethod
  fun getCustomerSavedPaymentMethodData(): Array<PaymentMethod>
  fun confirmWithCustomerDefaultPaymentMethod(
    cvc: String? = null, resultHandler: (PaymentResult) -> Unit
  )

  fun confirmWithCustomerLastUsedPaymentMethod(
    cvc: String? = null, resultHandler: (PaymentResult) -> Unit
  )

  fun confirmWithCustomerPaymentToken(
    paymentToken: String, cvc: String? = null, resultHandler: (PaymentResult) -> Unit
  )
}

package io.hyperswitch.paymentsheet

import android.os.Parcelable
import kotlinx.parcelize.Parcelize

/**
 * The result of an attempt to confirm a [PaymentIntent] or [SetupIntent].
 */
sealed class PaymentSheetResult : Parcelable {

  /**
   * The customer completed the payment or setup.
   * The payment may still be processing at this point; don't assume money has successfully moved.
   *
   * Your app should transition to a generic receipt view (e.g. a screen that displays "Your order
   * is confirmed!"), and fulfill the order (e.g. ship the product to the customer) after
   * receiving a successful payment event from Hyperswitch.
   *
   * See [Hyperswitch's documentation](https://hyperswitch.io)
   */
  @Parcelize
  data class Completed(
    val data: String
  ) : PaymentSheetResult()

  /**
   * The customer canceled the payment or setup attempt.
   */
  @Parcelize
  data class Canceled(
    val data: String
  ) : PaymentSheetResult()

  /**
   * The payment or setup attempt failed.
   * @param error The error encountered by the customer.
   */
  @Parcelize
  data class Failed(
    val error: Throwable,
  ) : PaymentSheetResult()
}

package io.hyperswitch.payments.paymentlauncher

import android.content.Intent
import android.os.Parcelable
import androidx.core.os.bundleOf
import kotlinx.parcelize.Parcelize

/**
 * Result to be passed to the callback of [PaymentLauncher]
 */
sealed class PaymentResult : Parcelable {
  @Parcelize
  class Completed(val data: String) : PaymentResult()

  @Parcelize
  class Failed(val throwable: Throwable) : PaymentResult()

  @Parcelize
  class Canceled(val data: String) : PaymentResult()

  @JvmSynthetic
  fun toBundle() = bundleOf(EXTRA to this)

  internal companion object {
    private const val EXTRA = "extra_args"

    @JvmSynthetic
    fun fromIntent(intent: Intent?): PaymentResult {
      return intent?.getParcelableExtra(EXTRA)
        ?: Failed(IllegalStateException("Failed to get PaymentResult from Intent"))
    }
  }
}

